package fr.definiday

import android.animation.ValueAnimator
import android.content.Context
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.drawable.AnimatedVectorDrawable
import android.graphics.drawable.Drawable
import android.view.ContextThemeWrapper
import android.widget.ImageView

/** Monsieur Glose: drawables generated by design/mascotte/android/make_android.js, dressed by theme overlays. */
object Glose {
    /** [res] themed with style Glose then each overlay of [styles] (pelage, pelote, accessoire). */
    fun drawable(ctx: Context, res: Int, styles: List<Int> = emptyList()): Drawable {
        val t = ContextThemeWrapper(ctx, R.style.Glose)
        styles.forEach { t.theme.applyStyle(it, true) }
        return t.getDrawable(res)!!
    }

    /** Glose showing one collection item: its pose, or the seated pose wearing it. */
    fun preview(ctx: Context, item: Unlocks.Item): Drawable =
        drawable(ctx, if (item.res != 0) item.res else R.drawable.glose_assis, listOf(item.style).filter { it != 0 })

    /** (Re)starts the view's animation from the beginning; stays a still image when animations are off (settings, battery saver). */
    fun play(v: ImageView) {
        val d = v.drawable as? AnimatedVectorDrawable ?: return
        d.reset()
        if (ValueAnimator.areAnimatorsEnabled()) d.start()
    }

    /** Still image (notifications, tests): the drawable fitted and centred in a w x h bitmap. */
    fun bitmap(ctx: Context, res: Int, w: Int, h: Int, styles: List<Int> = emptyList()): Bitmap {
        val b = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        val s = minOf(w, h)
        drawable(ctx, res, styles).apply { setBounds((w - s) / 2, (h - s) / 2, (w + s) / 2, (h + s) / 2) }.draw(Canvas(b))
        return b
    }
}
